{
  "claims": [
    {
      "claim": "Direct studies on rifampicin itself show measurable brain penetration after systemic administration: baboon PET estimated whole-brain concentrations of ~0.9–1.2 µg/ml and brain concentrations 3–4 times above MIC values, with a permeable BBB label; monkey brain tissue was 0.87 µg/g, mouse brain was 10.25 µg/ml, and human brain tissue was 0.29 µg/ml after intravenous infusion. These direct brain-exposure measurements support meaningful CNS access despite physicochemical liabilities.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 12"
      ],
      "record_ids": [
        "Record 12-2",
        "Record 12-3",
        "Record 12-4",
        "Record 12-5",
        "Record 12-6"
      ]
    },
    {
      "claim": "Rifabutin, a closely related rifamycin, achieved a brain/plasma ratio of ~0.856 and CSF/plasma ratio of ~0.227 in a rabbit TBM model, and ~50% CSF/serum penetration in HIV patients, indicating that rifamycin-class molecules can achieve meaningful CNS exposure in relevant infectious/inflammatory conditions.",
      "evidence_role": "supportive",
      "molecule_ids": [
        "Molecule 13"
      ],
      "record_ids": [
        "Record 13-1",
        "Record 13-2",
        "Record 13-3",
        "Record 13-7",
        "Record 13-8",
        "Record 13-9"
      ]
    },
    {
      "claim": "Contradictory evidence from the close analog rifapentine shows poor/undetectable CSF penetration in tuberculous meningitis patients and brain levels <20% of plasma, and one healthy-baboon PET study labeled rifampicin as poor penetrating; however, these observations do not negate the direct rifampicin brain concentrations above MIC values, especially under the inflamed meninges characteristic of tuberculous meningitis.",
      "evidence_role": "contradictory",
      "molecule_ids": [
        "Molecule 11",
        "Molecule 12"
      ],
      "record_ids": [
        "Record 11-1",
        "Record 11-2",
        "Record 11-3",
        "Record 11-4",
        "Record 12-1"
      ]
    }
  ],
  "final_prediction": "pass"
}

